'use strict';
const Phonics = (()=>{
 const data=PHONICS, byId=new Map(data.entries.map(e=>[e.id,e]));
 let lessonId='start',view='cards',cardIndex=0,compareKey='a',blendIndex=0,quiz=null;
 let rawProgress=null;try{rawProgress=JSON.parse(localStorage.getItem('abc-phonics-v1'));}catch{}
 let progress=PhonicsPractice.restore(rawProgress,data);lessonId=progress.last;
 cardIndex=Math.max(0,data.lessons.find(l=>l.id===lessonId).ids.indexOf(progress.cursors[lessonId]));
 const buffers=new Map(),pending=new Map();
 const lesson=()=>data.lessons.find(l=>l.id===lessonId),entries=()=>lesson().ids.map(id=>byId.get(id));
 function save(){try{localStorage.setItem('abc-phonics-v1',JSON.stringify(progress));}catch{$('#notice').textContent='这次可以正常玩，当前浏览器暂时无法保存发音记录。';}}
 function remember(id,followed=false){if(!progress.practised.includes(id))progress.practised.push(id);if(followed&&!progress.followed.includes(id))progress.followed.push(id);save();}
 function path(name){return 'audio/phonics/'+name+'.mp3?v=9';}
 async function load(name){if(buffers.has(name))return buffers.get(name);if(pending.has(name))return pending.get(name);const task=(async()=>{unlockAudio();if(!audioContext)throw Error('no audio context');const r=await fetch(path(name));if(!r.ok)throw Error('missing audio');const b=await audioContext.decodeAudioData(await r.arrayBuffer());buffers.set(name,b);return b;})();pending.set(name,task);try{return await task;}finally{pending.delete(name);}}
 function rawPlay(name,request){return new Promise(async(resolve)=>{
  try{const buffer=await load(name);if(request!==audioRequest||!sound||document.hidden||$('#parent').open)return resolve(false);if(audioContext.state!=='running')await audioContext.resume();if(request!==audioRequest||!sound||audioContext.state!=='running')return resolve(false);const source=audioContext.createBufferSource();source.buffer=buffer;source.connect(audioContext.destination);currentSource=source;source.onended=()=>{if(currentSource===source)currentSource=null;resolve(request===audioRequest&&sound);};source.start();setAudioStatus('♫ 正在播放发音');}
  catch{if(request!==audioRequest||!sound||document.hidden||$('#parent').open)return resolve(false);const a=new Audio(path(name));currentAudio=a;a.onended=()=>{if(currentAudio===a)currentAudio=null;resolve(request===audioRequest&&sound);};a.onerror=()=>{if(request===audioRequest)$('#notice').textContent='发音录音暂时没有加载成功，请检查网络后再点一次。';resolve(false);};try{setAudioStatus('准备发音…');await a.play();setAudioStatus('♫ 正在播放发音');}catch{if(request===audioRequest)$('#notice').textContent='请打开媒体音量，再点一次发音按钮。';resolve(false);}}
 });}
 async function sequence(keys,onStep){if(!sound){$('#notice').textContent='先点页面底部的「声音关」，打开声音后再听。';setAudioStatus($('#notice').textContent);return false;}stopVoice();unlockAudio();const request=audioRequest;$('#notice').textContent='';setAudioStatus('准备发音…');
  try{for(let i=0;i<keys.length;i++){if(request!==audioRequest||!sound)return false;if(keys[i]===null){onStep?.(i);continue;}onStep?.(i);const names=data.sounds[keys[i]][1];for(const name of(Array.isArray(names)?names:[names])){if(!await rawPlay(name,request))return false;}}return request===audioRequest;}
  finally{if(request===audioRequest){onStep?.(-1);setAudioStatus($('#notice').textContent||'');}}
 }
 function sayWord(word){WordAudio.play(word);}
 function ipa(s){return '/'+data.sounds[s][0]+'/';}
 function select(id,cardId=null){stopVoice();lessonId=id;progress.last=id;view='cards';cardIndex=Math.max(0,lesson().ids.indexOf(cardId||progress.cursors[id]));blendIndex=0;quiz=null;save();render();}
 function openCard(cardId){const owner=PhonicsPractice.lessonFor(cardId,data);if(owner)select(owner.id,cardId);}
 function shell(){const l=lesson();document.body.classList.add('phonics-mode');area.classList.add('phonics-activity');document.querySelector('.workspace').classList.add('phonics-layout');
 area.innerHTML=`<div class="activity-top"><span>PHONICS · 发音探险</span><span class="pill">先听声音，再试着拼读</span></div>
 <div class="phonics-heading"><h2>字母，还藏着不同的声音。</h2><p>这里学的是单词里的发音；ABC 的名称在「认识字母」里。</p></div>
 <div class="ph-stages" role="group" aria-label="自然拼读学习阶段">${[['single','1','字母音'],['combo','2','字母组合'],['magic','3','魔法 e'],['compare','4','多种读音']].map(([stage,num,title])=>`<button data-stage="${stage}" class="${view==='compare'?stage==='compare'?'on':'':l.stage===stage?'on':''}" aria-pressed="${view==='compare'?stage==='compare':l.stage===stage}"><small>${num}</small>${title}</button>`).join('')}</div>
 ${view==='compare'?'':`<div class="ph-lessons" role="group" aria-label="选择发音小组">${data.lessons.filter(x=>x.stage===l.stage).map(x=>`<button data-lesson="${x.id}" aria-pressed="${x.id===lessonId}" class="${x.id===lessonId?'on':''}">${x.title}<small>${x.subtitle}</small></button>`).join('')}</div><div class="ph-tabs" role="group" aria-label="选择发音活动">${[['cards','1','听音跟读'],['quiz','2','听音找卡'],['blend','3','拼成单词']].map(([v,icon,title])=>`<button data-ph-view="${v}" class="${view===v?'on':''}" aria-pressed="${view===v}">${icon} ${title}</button>`).join('')}</div>`}
 <div id="audioStatus" class="ph-audio-status" role="status" aria-live="polite"></div><div id="phBody"></div>`;
 area.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{stopVoice();if(b.dataset.stage==='compare'){view='compare';render();}else select(data.lessons.find(l=>l.stage===b.dataset.stage).id);});
 area.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>select(b.dataset.lesson));
 area.querySelectorAll('[data-ph-view]').forEach(b=>b.onclick=()=>{stopVoice();view=b.dataset.phView;if(view==='quiz'&&!quiz)makeQuiz();render();});
 renderSide();
 }
 function render(){shell();if(view==='cards')cards();else if(view==='quiz'){if(!quiz)makeQuiz();renderQuiz();}else if(view==='blend')blend();else compare();}
 function markedWord(e){return e.parts.map((p,i)=>{const match=e.g.includes('-')?(i===1||i===e.parts.length-1):p===e.g;return `<span class="${match?'ph-highlight':''}">${p}</span>`;}).join('');}
 function cards(){const pool=entries(),e=pool[cardIndex];progress.cursors[lessonId]=e.id;save();$('#phBody').innerHTML=`<div class="ph-card-top"><span>${lesson().title}</span><span>${cardIndex+1} / ${pool.length}</span></div><div class="ph-card"><div class="ph-glyph">${e.g}</div><button class="primary ph-hear" id="phHear" aria-label="听 ${e.g} 在 ${e.word} 中的发音">♫ 听这个发音</button><div class="ph-example"><span class="ph-emoji" aria-hidden="true">${e.emoji}</span><div><b>${markedWord(e)}</b><small>${e.cn}</small></div><button id="phWord" class="ph-icon" aria-label="听单词 ${e.word}">♫</button></div><p class="ph-rule">${e.note||`${e.g} 在 ${e.word} 里发这个音，听完跟着说一遍。`}</p></div><div class="controls ph-card-controls"><button class="secondary" id="phName" ${e.g.length===1?'':'hidden'}>听字母名称 ${e.g.toUpperCase()}</button><button class="secondary" id="phPractised">${progress.followed.includes(e.id)?'✓ 我跟读过了':'✓ 我也跟读一遍'}</button></div><details class="ph-parent-note"><summary>家长提示 · 口形与发音</summary><p><strong>${ipa(e.s)}</strong> ${data.sounds[e.s][2]} 辅音后不要额外加“呃”。音标供家长查看，不要求孩子背。</p>${e.more.length?`<p>同一个声音，还能这样写：${e.more.join('；')}。</p>`:''}${e.g==='qu'?'<p>q 的名称仍是 Q；这里练的是常见搭档 qu。</p>':''}</details><div class="bottom-controls"><button class="round-btn" id="phPrev" aria-label="上一个发音">‹</button><span>听一遍，跟一遍，就很好。</span><button class="${cardIndex===pool.length-1?'secondary ph-next-step':'round-btn'}" id="phNext" aria-label="${cardIndex===pool.length-1?'学完本组，进入听音练习':'下一个发音'}">${cardIndex===pool.length-1?'去找声音 →':'›'}</button></div>`;
 $('#phHear').onclick=()=>sequence([e.s]);$('#phWord').onclick=()=>sayWord(e.word);$('#phName').onclick=()=>speak(e.g.toUpperCase());$('#phPractised').onclick=()=>{remember(e.id,true);$('#phPractised').textContent='✓ 我跟读过了';renderSide();};$('#phPrev').onclick=()=>{stopVoice();cardIndex=(cardIndex+pool.length-1)%pool.length;cards();renderSide();};$('#phNext').onclick=()=>{stopVoice();if(cardIndex===pool.length-1){view='quiz';makeQuiz();render();}else{cardIndex++;cards();renderSide();}};
 }
 function renderSide(){const aside=document.querySelector('aside');if(mode!=='phonics')return;const pool=(view==='quiz'&&quiz?.review)?quiz.pool:entries();aside.innerHTML=`<div class="aside-head"><h2>${view==='compare'?'声音变变看':view==='quiz'&&quiz?.review?'错题发音卡':'这一小组的声音'}</h2><span>${view==='compare'?'对比认识':pool.length+' 张'}</span></div><p class="aside-copy">${view==='compare'?'同样的字母，要放在单词里听。':'点一张卡，听听它在单词里的声音。'}</p>${view==='compare'?`<div class="ph-compare-index">${Object.keys(data.variants).map(g=>`<button data-compare="${g}" class="${g===compareKey?'selected':''}" aria-pressed="${g===compareKey}">${g}</button>`).join('')}</div>`:`<div class="ph-grid">${pool.map((e,i)=>`<button data-ph-card="${e.id}" class="${view==='cards'&&i===cardIndex?'selected':''}" aria-label="学习 ${e.g}，例词 ${e.word}" aria-pressed="${view==='cards'&&i===cardIndex}"><b>${e.g}</b><small>${e.word}</small>${progress.practised.includes(e.id)?'<span class="ph-check" aria-label="练习过">✓</span>':''}</button>`).join('')}</div>`}<div class="ph-progress-note"><b>✦ 已练习 ${progress.practised.length} / ${data.entries.length} 张卡</b><p>做过练习不等于掌握，慢慢熟悉就好。</p>${progress.review.length?`<button class="secondary" id="phReview">再练 ${progress.review.length} 张错题卡</button>`:''}</div><div class="ph-side-tip"><b>今天的小任务</b><p>${view==='quiz'&&quiz?.review?'先回听上次没分清的声音，不急着加新内容。':lessonId==='start'?'先练 s a t p i n，再试着拼 sat、pin。':`这次练「${lesson().title}」。先听音跟读，再找声音、拼单词。`}每次约 5 分钟就好。</p><button class="quiet" id="phGoStart">回到第一小组 ↗</button></div><details class="ph-side-guide"><summary>给家长：怎么陪着练？</summary><p>先听音、模仿，再看例词。组合 sh 发一个音；st 中 s 和 t 保留各自的音。字母音学熟后再接触多种读音，不需要一次背完。</p><p>发音录音采用英式声音示范；完整单词使用有道词典的在线英式发音，需要联网。先听一遍，再让孩子跟读，陪练时以孩子老师的发音为准。</p></details>`;
 aside.querySelectorAll('[data-ph-card]').forEach(b=>b.onclick=()=>{openCard(b.dataset.phCard);});aside.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{stopVoice();compareKey=b.dataset.compare;render();});$('#phGoStart').onclick=()=>select('start');if($('#phReview'))$('#phReview').onclick=()=>{stopVoice();view='quiz';makeQuiz(true);render();};
 }
 function makeQuiz(review=false){const pool=review?progress.review.map(id=>byId.get(id)):entries();const unique=shuffle(pool);quiz={pool:[...pool],targets:Array.from({length:5},(_,i)=>unique[i%unique.length]),step:0,first:0,attempts:0,answered:false,heard:false,options:[],review,awarded:false};prepareQuestion();}
 function prepareQuestion(){if(quiz.step>=5)return;const target=quiz.targets[quiz.step];quiz.options=PhonicsPractice.distinctOptions(target,PhonicsPractice.candidates(target,quiz.pool,progress.practised,data),shuffle);quiz.attempts=0;quiz.answered=false;quiz.heard=false;}
 function renderQuiz(){if(quiz.step===5){if(!quiz.awarded){saved.stars++;quiz.awarded=true;persist();stats();}$('#phBody').innerHTML=`<div class="finish ph-finish"><div class="award">✦</div><h2>声音小探险完成！</h2><p>听了 5 题 · ${quiz.first} 题第一次就找到了。<br>收好一颗探险星，休息一下也很好。</p><div class="controls"><button class="primary" id="phTryBlend">${quiz.review?'回到本组拼单词 →':'试试拼成单词 →'}</button><button class="secondary" id="phAgain">再练一轮</button></div><div class="controls"><button class="quiet" id="phBackCards">回到发音卡</button></div></div>`;$('#phTryBlend').onclick=()=>{stopVoice();view='blend';blendIndex=0;render();};$('#phAgain').onclick=()=>{makeQuiz(quiz.review&&progress.review.length>0);renderQuiz();};$('#phBackCards').onclick=()=>{view='cards';quiz=null;render();};renderSide();return;}
 const q=quiz,questionStep=q.step,target=q.targets[q.step];$('#phBody').innerHTML=`<div class="ph-card-top"><span>${q.review?'错题再练习':'听的是发音，不是 ABC 名称'}</span><span>第 ${q.step+1} / 5 题</span></div><div class="progress"><span style="width:${q.step*20}%"></span></div><div class="question ph-listen-question"><div class="ph-sound-orb" aria-hidden="true">♫</div><h2>这个声音，藏在哪张卡里？</h2><p>先听发音，再选一张卡。</p><button class="primary" id="phQuestion">♫ 听题目</button></div><div class="choices ph-choices ${q.options.length===2?'ph-two-choices':''}">${q.options.map(e=>`<button class="choice" data-ph-answer="${e.id}"><b>${e.g}</b><small>${e.word}</small></button>`).join('')}</div><div class="feedback" id="phFeedback" role="status">点「听题目」后，再选答案吧。</div><div class="controls"><button class="secondary" id="phHint">给我一个提示</button><button class="primary" id="phContinue" hidden>下一题</button></div>`;
 $('#phQuestion').onclick=async()=>{const ok=await sequence([target.s]);if(ok&&quiz===q&&q.step===questionStep&&mode==='phonics'&&view==='quiz'){q.heard=true;if(!q.answered)$('#phFeedback').textContent='听到了吗？试着选一张卡。';}};
 area.querySelectorAll('[data-ph-answer]').forEach(b=>b.onclick=()=>{if(q.answered)return;if(!q.heard){$('#phFeedback').textContent='先点「听题目」，听完再选哦。';return;}q.attempts++;const e=byId.get(b.dataset.phAnswer);if(e.id===target.id){q.answered=true;remember(target.id);if(q.attempts===1){q.first++;progress.review=progress.review.filter(id=>id!==target.id);save();}b.classList.add('correct');area.querySelectorAll('[data-ph-answer]').forEach(x=>x.disabled=true);$('#phFeedback').textContent=`找到了！${target.g} 在 ${target.word} 中发 ${ipa(target.s)}。`;$('#phContinue').hidden=false;$('#phHint').hidden=true;renderSide();}else{b.classList.add('wrong');b.disabled=true;if(!progress.review.includes(target.id))progress.review.push(target.id);save();$('#phFeedback').textContent='再听一次，换张卡试试看。';sequence([target.s]);renderSide();}});
 $('#phHint').onclick=()=>{q.attempts++;q.heard=true;$('#phFeedback').textContent=`找找 ${target.word} 这张卡。`;sayWord(target.word);};$('#phContinue').onclick=()=>{stopVoice();q.step++;prepareQuestion();renderQuiz();};}
 function blend(){const l=lesson(),nextLesson=data.lessons[data.lessons.indexOf(l)+1],pool=l.blend?l.blend.map(([word,cn,emoji,parts,keys])=>({word,cn,emoji,parts,keys})):entries();blendIndex%=pool.length;const e=pool[blendIndex];const count=e.keys.filter(Boolean).reduce((n,k)=>n+(Array.isArray(data.sounds[k][1])?data.sounds[k][1].length:1),0);
 $('#phBody').innerHTML=`<div class="ph-card-top"><span>点声音小积木，再把它们连起来</span><span>${blendIndex+1} / ${pool.length}</span></div><div class="ph-blend-picture" aria-hidden="true">${e.emoji}</div><h3 class="ph-blend-word">${e.word}</h3><p class="ph-blend-cn">${e.cn} · ${count} 个音${l.stage==='magic'?' · 末尾 e 不单独发音':''}</p><div class="ph-blocks">${e.parts.map((p,i)=>`<button data-block="${i}" class="${e.keys[i]===null?'silent':''}" aria-label="${e.keys[i]===null?'末尾 e 不发音':`听 ${p} 的发音`}"><b>${p}</b><span>${e.keys[i]===null?'不发音':Array.isArray(data.sounds[e.keys[i]][1])?'••':'•'}</span></button>`).join('')}</div><p class="ph-rule">${l.stage==='magic'?'同色的元音和末尾 e 是隔开的搭档。末尾 e 帮忙，但自己不单独发音。':'一块积木不一定只写一个字母。点一点，听每个音。'}</p><div class="controls"><button class="primary" id="phBlend">♫ 逐音听一遍</button><button class="secondary" id="phWhole">听完整单词</button></div><p class="ph-blend-help">听完试着自己连读；完整单词可以再听一次。</p><div class="bottom-controls"><button class="round-btn" id="phBlendPrev" aria-label="上一个单词">‹</button><span>把小声音，连成一个词。</span><button class="${blendIndex===pool.length-1?'secondary ph-next-step':'round-btn'}" id="phBlendNext" aria-label="${blendIndex===pool.length-1?nextLesson?'看看下一学习组':'再看本组第一个单词':'下一个单词'}">${blendIndex===pool.length-1?nextLesson?'下一小组 →':'再看一遍':'›'}</button></div>`;
 const highlight=i=>{if(mode!=='phonics'||view!=='blend')return;area.querySelectorAll('[data-block]').forEach(b=>b.classList.toggle('playing',Number(b.dataset.block)===i));};
 area.querySelectorAll('[data-block]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.block);if(e.keys[i]===null){stopVoice();highlight(-1);$('#notice').textContent='末尾的 e 不单独发音，它和前面的元音是搭档。';}else sequence([e.keys[i]],step=>highlight(step===-1?-1:i));});
 if(l.stage==='magic'){const blocks=area.querySelectorAll('[data-block]');blocks[1].classList.add('magic-pair');blocks[blocks.length-1].classList.add('magic-pair');}
 $('#phBlend').onclick=()=>sequence(e.keys,highlight);$('#phWhole').onclick=()=>{highlight(-1);sayWord(e.word);};$('#phBlendPrev').onclick=()=>{stopVoice();blendIndex=(blendIndex+pool.length-1)%pool.length;blend();};$('#phBlendNext').onclick=()=>{stopVoice();if(blendIndex===pool.length-1&&nextLesson)select(nextLesson.id);else{blendIndex=(blendIndex+1)%pool.length;blend();}};
 }
 function compare(){const variants=data.variants[compareKey];$('#phBody').innerHTML=`<label class="ph-compare-select">想听哪组字母？<select id="phCompareSelect" aria-label="选择需要比较的字母">${Object.keys(data.variants).map(g=>`<option value="${g}" ${g===compareKey?'selected':''}>${g}</option>`).join('')}</select></label><div class="ph-compare-heading"><span class="ph-compare-big">${compareKey}</span><div><h3>同样的字母，不一样的声音。</h3><p>每次选一张听，比较它们的口形。</p></div></div><div class="ph-variants">${variants.map(([s,word,cn,emoji],i)=>`<article><span class="ph-variant-emoji" aria-hidden="true">${emoji}</span><b>${word.replace(compareKey,`<span class="ph-highlight">${compareKey}</span>`)}</b><small>${cn}</small><div class="ph-variant-sound">${ipa(s)}</div><button class="primary" data-variant-sound="${i}" aria-label="听 ${compareKey} 在 ${word} 中的发音">♫ 听发音</button><button class="quiet" data-variant-word="${i}">听单词</button></article>`).join('')}</div><p class="ph-rule ph-compare-rule">${data.compareNotes[compareKey]}</p><div class="ph-gentle-note">🌱 先把常见音学熟，再慢慢认识变化。这里列的是入门常见读音，并非全部。</div><div class="controls"><button class="secondary" id="phCompareStart">回到入门字母音</button></div>`;
 $('#phCompareSelect').onchange=e=>{stopVoice();compareKey=e.target.value;render();};area.querySelectorAll('[data-variant-sound]').forEach(b=>b.onclick=()=>sequence([variants[Number(b.dataset.variantSound)][0]]));area.querySelectorAll('[data-variant-word]').forEach(b=>b.onclick=()=>sayWord(variants[Number(b.dataset.variantWord)][1]));$('#phCompareStart').onclick=()=>select('start');
 }
 function reset(){progress=PhonicsPractice.restore(null,data);lessonId='start';quiz=null;cardIndex=0;view='cards';save();}
 function leave(){document.body.classList.remove('phonics-mode');area.classList.remove('phonics-activity');document.querySelector('.workspace').classList.remove('phonics-layout');}
 return {render,leave,reset,select,sequence};
})();
